#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

struct Point {
  std::int64_t x_mm = 0;
  std::int64_t y_mm = 0;
  friend bool operator==(const Point&, const Point&) = default;
};

// A value type: its members are values, so copies are independent and == compares contents.
struct Path {
  std::string frame;
  std::vector<Point> points;
  friend bool operator==(const Path&, const Path&) = default;
};

int main() {
  const Path original{.frame = "map", .points = {{.x_mm = 0, .y_mm = 0}, {.x_mm = 1500, .y_mm = 0}}};
  Path copy = original;
  std::cout << std::boolalpha << "equal after the copy: " << (copy == original) << '\n';
  copy.points.push_back({.x_mm = 1500, .y_mm = 900});
  copy.frame = "odom";
  std::cout << "equal after changing the copy: " << (copy == original) << '\n';
  std::cout << "original: " << original.frame << ", " << original.points.size() << " points\n";
}

