#include <algorithm>
#include <iostream>
#include <span>
#include <string_view>
#include <vector>

void show(std::string_view label, std::span<const int> values) {
  std::cout << label << ':';
  for (const int v : values) std::cout << ' ' << v;
  std::cout << '\n';
}

int main() {
  std::vector<int> ranges_cm{120, 400, 70, 400, 70, 30};
  std::vector<int> copy = ranges_cm;

  // Remove every reading equal to the largest one.
  std::erase(ranges_cm, *std::ranges::max_element(ranges_cm));  // passes a reference into the vector
  show("by reference", ranges_cm);

  const int largest = *std::ranges::max_element(copy);  // a value of its own
  std::erase(copy, largest);
  show("by value    ", copy);
}

