#include <concepts>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <string_view>
#include <utility>
#include <vector>

struct Shape {
  std::ptrdiff_t rows = 0;
  std::ptrdiff_t cols = 0;
  friend bool operator==(const Shape&, const Shape&) = default;
};

struct Cell {
  std::ptrdiff_t row = 0;
  std::ptrdiff_t col = 0;
};

// A dense matrix of doubles with value semantics: copies are independent, and == compares shape and contents.
class Matrix {
 public:
  Matrix() = default;
  explicit Matrix(Shape shape) : shape_(shape), cells_(cell_count(shape)) {}

  [[nodiscard]] static Matrix identity(std::ptrdiff_t n) {
    Matrix m({.rows = n, .cols = n});
    for (std::ptrdiff_t i = 0; i < n; ++i) m[{.row = i, .col = i}] = 1.0;
    return m;
  }

  [[nodiscard]] Shape shape() const { return shape_; }
  [[nodiscard]] double& operator[](Cell c) { return cells_[index(c)]; }
  [[nodiscard]] double operator[](Cell c) const { return cells_[index(c)]; }

  [[nodiscard]] Matrix transposed() const {
    Matrix t({.rows = shape_.cols, .cols = shape_.rows});
    for (std::ptrdiff_t r = 0; r < shape_.rows; ++r) {
      for (std::ptrdiff_t c = 0; c < shape_.cols; ++c) t[{.row = c, .col = r}] = (*this)[{.row = r, .col = c}];
    }
    return t;
  }

  // Compares shape_ first, then cells_: the declaration order below.
  friend bool operator==(const Matrix&, const Matrix&) noexcept = default;

 private:
  [[nodiscard]] static std::size_t cell_count(Shape s) {
    if (s.rows < 0 || s.cols < 0) throw std::invalid_argument("negative matrix shape");
    return static_cast<std::size_t>(s.rows * s.cols);
  }
  [[nodiscard]] std::size_t index(Cell c) const { return static_cast<std::size_t>(c.row * shape_.cols + c.col); }

  Shape shape_;
  std::vector<double> cells_;
};

[[nodiscard]] Matrix operator*(const Matrix& a, const Matrix& b) {
  if (a.shape().cols != b.shape().rows) throw std::invalid_argument("shapes don't match for a product");
  Matrix product({.rows = a.shape().rows, .cols = b.shape().cols});
  for (std::ptrdiff_t r = 0; r < a.shape().rows; ++r) {
    for (std::ptrdiff_t c = 0; c < b.shape().cols; ++c) {
      double sum = 0.0;
      for (std::ptrdiff_t k = 0; k < a.shape().cols; ++k) sum += a[{.row = r, .col = k}] * b[{.row = k, .col = c}];
      product[{.row = r, .col = c}] = sum;
    }
  }
  return product;
}

static_assert(std::regular<Matrix>);
static_assert(noexcept(std::declval<const Matrix&>() == std::declval<const Matrix&>()));

void show(std::string_view label, const Matrix& m) {
  std::cout << label << " (" << m.shape().rows << 'x' << m.shape().cols << "):";
  for (std::ptrdiff_t r = 0; r < m.shape().rows; ++r) {
    std::cout << " [";
    for (std::ptrdiff_t c = 0; c < m.shape().cols; ++c) std::cout << (c == 0 ? "" : " ") << m[{.row = r, .col = c}];
    std::cout << ']';
  }
  std::cout << '\n';
}

int main() {
  Matrix a({.rows = 2, .cols = 3});
  a[{.row = 0, .col = 0}] = 1.0;
  a[{.row = 0, .col = 2}] = 2.5;
  a[{.row = 1, .col = 1}] = -1.0;

  Matrix copy = a;
  std::cout << std::boolalpha << "1 copy == a: " << (copy == a) << '\n';
  copy[{.row = 1, .col = 2}] = 4.0;
  std::cout << "2 after changing the copy: " << (copy == a) << '\n';
  show("  a", a);
  show("  copy", copy);

  const Matrix wide({.rows = 2, .cols = 3});
  const Matrix tall({.rows = 3, .cols = 2});
  std::cout << "3 2x3 zeros == 3x2 zeros: " << (wide == tall) << '\n';

  Matrix assigned;
  assigned = a;
  std::cout << "4 after assigned = a: " << (assigned == a) << '\n';

  std::cout << "5 a transposed twice == a: " << (a.transposed().transposed() == a) << '\n';
  std::cout << "5 a * identity == a: " << (a * Matrix::identity(3) == a) << '\n';
  show("  a * a transposed", a * a.transposed());
}

#include <concepts>
#include <format>
#include <iostream>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

struct Counts {
  int copies = 0;
};

// Stands in for a scan's heavy payload, and counts how often it is copied.
class Payload {
 public:
  explicit Payload(Counts& counts) : counts_(&counts) {}
  Payload(const Payload& other) : counts_(other.counts_) { ++counts_->copies; }
  Payload(Payload&&) noexcept = default;
  Payload& operator=(const Payload& other) {
    counts_ = other.counts_;
    ++counts_->copies;
    return *this;
  }
  Payload& operator=(Payload&&) noexcept = default;
  ~Payload() = default;

 private:
  Counts* counts_;
};

struct Scan {
  std::string frame;
  Payload ranges;
};

class ScanLog {
 public:
  void add(Scan scan) { scans_.push_back(std::move(scan)); }
  [[nodiscard]] const Scan& latest() const { return scans_.back(); }
  [[nodiscard]] const std::vector<Scan>& all() const { return scans_; }

 private:
  std::vector<Scan> scans_;
};

[[nodiscard]] std::size_t frame_length_by_value(Scan scan) { return scan.frame.size(); }
[[nodiscard]] std::size_t frame_length_by_ref(const Scan& scan) { return scan.frame.size(); }

void measure(Counts& counts, std::string_view label, std::invocable auto step) {
  const int before = counts.copies;
  step();
  std::cout << std::format("{:<34}copies {}\n", label, counts.copies - before);
}

int main() {
  Counts counts;
  ScanLog log;
  log.add({.frame = "front_lidar", .ranges = Payload(counts)});
  log.add({.frame = "rear_lidar", .ranges = Payload(counts)});
  log.add({.frame = "front_lidar", .ranges = Payload(counts)});

  std::size_t total = 0;
  measure(counts, "for (auto scan : all())", [&] {
    for (auto scan : log.all()) total += scan.frame.size();
  });
  measure(counts, "for (const auto& scan : all())", [&] {
    for (const auto& scan : log.all()) total += scan.frame.size();
  });
  measure(counts, "const auto latest = log.latest()", [&] {
    const auto latest = log.latest();
    total += latest.frame.size();
  });
  measure(counts, "const auto& latest = log.latest()", [&] {
    const auto& latest = log.latest();
    total += latest.frame.size();
  });
  measure(counts, "frame_length_by_value(latest)", [&] { total += frame_length_by_value(log.latest()); });
  measure(counts, "frame_length_by_ref(latest)", [&] { total += frame_length_by_ref(log.latest()); });
  measure(counts, "[scan] capture", [&] {
    const auto size_of = [scan = log.latest()] { return scan.frame.size(); };
    total += size_of();
  });
  measure(counts, "[&scan] capture", [&] {
    const Scan& scan = log.latest();
    const auto size_of = [&scan] { return scan.frame.size(); };
    total += size_of();
  });
  std::cout << "characters counted: " << total << '\n';
}

