#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <string>
#include <utility>
#include <vector>

struct Counts {
  int copies = 0;
};

// A large map, loaded once and never changed. It counts how often it is copied.
class OccupancyMap {
 public:
  OccupancyMap(Counts& counts, std::int64_t cells)
      : counts_(&counts), cells_(static_cast<std::size_t>(cells)) {}
  OccupancyMap(const OccupancyMap& other) : counts_(other.counts_), cells_(other.cells_) { ++counts_->copies; }
  OccupancyMap& operator=(const OccupancyMap& other) {
    counts_ = other.counts_;
    cells_ = other.cells_;
    ++counts_->copies;
    return *this;
  }
  OccupancyMap(OccupancyMap&&) noexcept = default;
  OccupancyMap& operator=(OccupancyMap&&) noexcept = default;
  ~OccupancyMap() = default;
  [[nodiscard]] std::int64_t cell_count() const { return std::ssize(cells_); }

 private:
  Counts* counts_;
  std::vector<std::int8_t> cells_;
};

// Every robot carries its own copy of the map.
struct RobotOwningMap {
  std::string name;
  std::int64_t x_mm = 0;
  OccupancyMap map;
};

// Every robot is still a value, and the map is shared. Nobody can change it, so sharing it is safe.
struct Robot {
  std::string name;
  std::int64_t x_mm = 0;
  std::shared_ptr<const OccupancyMap> map;
};

int main() {
  constexpr std::int64_t cells = 1'000'000;

  Counts owning_counts;
  const RobotOwningMap prototype{.name = "amr", .map = OccupancyMap(owning_counts, cells)};
  const std::vector<RobotOwningMap> heavy_fleet(20, prototype);
  std::cout << std::format("map by value:      {} map copies for {} robots\n", owning_counts.copies,
                           heavy_fleet.size());

  Counts shared_counts;
  const auto map = std::make_shared<const OccupancyMap>(shared_counts, cells);
  std::vector<Robot> fleet(20, Robot{.name = "amr", .map = map});
  std::cout << std::format("map by shared_ptr: {} map copies for {} robots, {} owners of the map\n",
                           shared_counts.copies, fleet.size(), map.use_count());

  fleet[1].name = "amr_2";
  fleet[1].x_mm = 1500;
  std::cout << std::format("{} at {} mm, {} at {} mm, both seeing {} cells\n", fleet[0].name, fleet[0].x_mm,
                           fleet[1].name, fleet[1].x_mm, fleet[1].map->cell_count());
}

#include <iostream>
#include <limits>

struct Reading {
  double range_m = 0.0;
  friend bool operator==(const Reading&, const Reading&) = default;
};

int main() {
  const Reading nothing_seen{.range_m = std::numeric_limits<double>::quiet_NaN()};
  const Reading copy = nothing_seen;
  std::cout << std::boolalpha << "copy == original: " << (copy == nothing_seen) << '\n';
}
